WITH Installs AS (SELECT player_id, MIN(event_date) AS install_dt FROM Activity GROUP BY player_id) SELECT i.install_dt, COUNT(i.player_id) AS installs, ROUND(COUNT(a.player_id) / COUNT(i.player_id), 2) AS Day1_retention FROM Installs i LEFT JOIN Activity a ON i.player_id = a.player_id AND a.event_date = DATE_ADD(i.install_dt, INTERVAL 1 DAY) GROUP BY i.install_dt;
